// 初始化参数
const accountName = '饼干哥哥AGI';
const apiKey = 'JZLdc9670be1403c05cJZLdc9670be1403c05c';
const baseUrl = 'https://www.dajiala.com/fbmain/monitor/v3/post_history';

return [{
  json: {
    accountName,
    apiKey,
    baseUrl,
    currentPage: 1,
    allArticles: [],
    totalPages: 0
  }
}];

// 处理API返回的数据
const response = $input.first().json;

if (response.code !== 0) {
  throw new Error(`API错误: ${response.msg} (code: ${response.code})`);
}

const articles = response.data || [];
const totalPage = response.total_page || 1;
const currentPage = $input.first().json.currentPage;
const allArticles = $input.first().json.allArticles || [];

// 合并文章
allArticles.push(...articles);

// 计算进度
const progress = Math.round((currentPage / totalPage) * 100);

console.log(`✅ 第 ${currentPage}/${totalPage} 页获取成功，本页 ${articles.length} 篇文章，累计 ${allArticles.length} 篇 (${progress}%)`);

return [{
  json: {
    ...$input.first().json,
    articles,
    allArticles,
    totalPages: totalPage,
    hasMore: currentPage < totalPage,
    nextPage: currentPage + 1,
    progress,
    accountInfo: {
      nickname: response.mp_nickname,
      wxid: response.mp_wxid,
      ghid: response.mp_ghid,
      totalNum: response.total_num,
      remainMoney: response.remain_money,
      costMoney: response.cost_money
    }
  }
}];

// 准备下一页请求
const current = $input.first().json;

return [{
  json: {
    ...current,
    currentPage: current.nextPage
  }
}];

// 构建最终输出
const data = $input.first().json;
const timestamp = new Date().toISOString().replace(/[:.]/g, '-');

const output = {
  metadata: {
    accountName: data.accountName,
    fetchTime: new Date().toISOString(),
    totalPages: data.totalPages,
    currentPage: data.currentPage - 1,
    totalArticles: data.allArticles.length,
    accountInfo: data.accountInfo
  },
  articles: data.allArticles.map((article, index) => ({
    index: index + 1,
    title: article.title,
    url: article.url,
    publishTime: article.post_time_str,
    timestamp: article.post_time,
    digest: article.digest,
    coverUrl: article.cover_url,
    isOriginal: article.original === 1,
    position: article.position,
    type: article.item_show_type === 0 ? '图文' : '其他',
    status: article.msg_status === 2 ? '正常' : '异常'
  }))
};

console.log(`🎉 抓取完成! 共 ${output.articles.length} 篇文章`);

return [{ json: output }];
